INSERT INTO `handel` (`id`, `datum`, `text`, `autor`, `bezug`) VALUES
(1, '2008-11-21 20:52:17', 'Seine Sie gegrüßt,\r\n\r\ndie [b]GCC[/b] freut sich die diesjährige Handelssaison eröffnen zu dürfen und bietet interessierten 60t reinstes Duranium zum Kauf an. Bitte unterbreiten Sie Ihre Angebot über den Subraumkanal 11. Akzeptiert wird derzeit leider nur Baumaterial als Tauschware.\r\n\r\nIch wünsche Ihnen noch einen profitablen Abend.', 11, 'HANDEL-0');
