INSERT INTO `item` (`id`, `name`, `bild`, `beschreibung`, `benutzbar`, `qitem`) VALUES
(8, 'Computerchip', 'testitem.jpg', 'Da du von Computern soviel verstehst wie ein Klingone von Feingefuehl, wirst du aus dem Stueck Metall nicht wirklich schlau.', 0, 0),
(10, 'Warpkern', '', 'Dies ist ein Warpkern eines romulanischen Schiffes... \r\nDa war doch jemand der das unbedingt haben wollte!', 0, 1),
(11, 'Lebkuchen', 'lebkucken.gif', 'Sie sehen sehr lecker aus.\r\nFinger weg! Diese sind f&uuml;r Wichtel bestimmt.', 0, 1),
(12, 'Carbonith&uuml;lle', 'carbonit.jpg', 'Ein Mensch ist hier in Carbonit eingefroren.\r\nNiqolouz scheint aber zu wissen wie man das beheben kann.', 1, 1);
INSERT INTO `kn` (`id`, `channel`, `datum`, `text`, `autor`, `bezug`, `edit`) VALUES
(1, 1, '2008-11-12 17:27:24', 'Willkommen', 1, 'KN-0', 0),
(2, 1, '2008-11-14 17:48:55', '[i]Interessant, hier scheint es Leben zu geben. Nil-Nischla, setzten Sie einen Wirt in das Al Niyat-System. Ruhm und Ehre für unsere Zunft sollen auch in diesem gottlosen Sektor Einzug halten. Wir, [spieler:10], werden die niederen Lebensformen studieren und analysieren, noch ist es nicht Zeit uns zu erkennen zu geben. \r\n\r\nDoch bald....[/i]', 10, 'KN-0', 0),
(3, 1, '2012-04-08 17:56:27', 'ich üüßß', 1, 'KN-2', 0),
(4, 1, '2008-11-17 12:47:43', 'verschoben', 1, 'KN-6', 0),
(5, 1, '2008-11-20 16:47:48', '[i].... eingehende Transmission ....\r\n.... Absender: [Allianz: 2] ....\r\n.... Kosten trägt der Empfänger ....[/i]\r\n\r\nWerte profitliebende Völker dieses Quadranten,\r\nwerte Warenbörseninspizienten,\r\nwerte Kleinstmengenkäufer,\r\nwerte Großabnehmer,\r\n\r\nheute hat sich Ungeheuerliches ereignet.\r\n\r\nUnser Warenbörsensystem wurde flächendeckend durch die kleinohrigen [Spieler: 4] zerstört. Bis auf weiteres können wir daher ein zentrales Handelssystem nicht zur Verfügung stellen. Handels Sie daher am Besten mit Ihren Nachbarvölkern. Wir sind auch gern bereit, Sie beim Transport der Waren zu unterstützen. \r\n\r\n ...  [i][farbe:#966400]Norax[/farbe] grinst verschmitzt[/i] ... Gegen eine kleine Bestechung selbstverständlich.\r\n\r\nWie die Vulkanier - zumindest nach unseren Geschichtsbüchern - zu sagen pflegen... Leben Sie lang ... und wir profitabel...\r\n\r\n[farbe:#966400]Norax[/farbe] \r\nstellvertretender Handelsminister und oberster Materialakquisiteur der [Spieler: 3]\r\n\r\n[i].... Ende der Transmission ....\r\n.... Kosten: 2 Dilithiumkristalle und 1 Tonne Erz ....\r\n.... Erz an Sendestation übermittelt - Kistalle durch die [Spieler: 3] eingezogen ....[/i]\r\n\r\n', 3, 'KN-0', 0),
(6, 1, '2008-11-22 12:36:12', '[i]Zentralcomputer öffnet eine Verbindung zum Subraumkommunikationsnetzwerk.\r\nEingehende Transmission.\r\n\r\nLegat [farbe:#ff9600]Peran Damir[/farbe], Detapa Rat, Cardassia Prime, Alpha-Quadrant, Milchstraße.[/i]\r\n\r\n[b]NA-pri YO-ten,\r\n\r\nals Oberhaupt des cardassianischen Volkes will ich Sie in Kenntniss darüber setzen, das die Union einen Stützpunkt in der hiesigen Antila-Zerggalaxie errichtet hat. Die genauen Koordinaten des, von uns eingenommen, Systems werden jedoch nicht öffentlich bekanntgegeben.\r\n\r\nEine Warnung möchte ich dennoch aussprechen. Sollten Sie auf unser Territorium treffen und beschließen in dieses System einzufliegen, übernehme ich keinerlei Verantwortung dafür, ob ihr Schiff sicher wieder herausfindet. Unsere Streitmacht patrouliert in steten Intervallen durch unser Sternensystem und wird jeden Eindringling ohne Warnung aus diesem entfernen.\r\n\r\nDoch seien Sie versichert, das wir nur unsere Bürger schützen wollen. Zu gegebener Zeit werden mächtige Raumstationen um unser System herum gebaut werden, von denen viele der Öffentlichkeit frei zur Verfügung stehen werden. Auf ihnen werden Sie Gelegenheit haben Geschäfte zu errichten, Handelsaufträge entgegenzunehmen oder einfach einen Zwischenstopp einzulegen.\r\n\r\nDayvs-GE-ve.[/b]\r\n\r\n[i]Ende der Transmission.\r\nZentralcomputer schließt die Verbindung zum Subraumkommunikationsnetzwerk.[/i]', 8, 'KN-0', 0),
(7, 1, '2008-12-11 17:07:04', '[i][spieler:11] erscheint auf dem Monitor und beginnt zu sprechen:[/i]\r\n\r\nAn den Kommandeur der [spieler:58],\r\n\r\ndie Strafexpeditionen gegen ihre Organisation, ausgelöst durch ihren dreisten Diebstahl von Eigentum der [b]GCC[/b], wurden am heutigen Tage zum Abschluss gebracht. Ihnen wurde Ihre gesamte militärische Operationsbasis entzogen. \r\nLassen Sie sich dies eine Warnung sein und vergreifen Sie sich NIE WIEDER am Eigentum der [b]GCC[/b] oder dem Eigentum von Staaten, Personen oder Organisationen, welche unter dem Schutz der [b]GCC[/b] stehen.\r\n\r\nIch wünsche Ihnen noch einen angenehmen Tag.\r\n\r\n[i]Der Bildschirm wird dunkel.[/i]', 11, 'KN-0', 0),
(8, 1, '2012-04-08 17:56:01', 'test', 1, 'KN-0', 0),
(9, 1, '2012-04-08 19:51:11', 'äüöß ss', 1, 'KN-0', 0),
(10, 2, '2008-11-15 21:07:28', '[i]Die kleine Transportflotte schwenke in den Orbit des Klasse M-Planeten ein. Nach der Entdeckung des Iconia-Portals war klar, daß bald eine wahre Flut aus Abenteurer und Kolonisten zu diesen neuen Ufern aufbrechen würde. Es blieb [spieler:11] gar nichts anderes übrig, als diesen neuen Markt zu erschließen. Doch wollte man wirklichen Profit erwirtschaften, mußten die Transportkosten niedrig gehalten werden. Wollte man die Waren ständig über das Portal verschiffen, würde dies eine gigantische Transportflotte erfordern, von der notwendigen Eskorte erst gar nicht zu reden. Und wer weis schon, wie lange dieses alte Ding noch durchhält. Nein, es gab keine Alternative zur Errichtung eigener Produktionsanlagen in dieser Galaxis. Nun hieß es nicht untätig zu bleiben und die Vormachtstellung der [/i][b]GCC[i][/b] auch in diesem Teil des Alls zu verteidigen. Die Schiffe setzten zur Landung an. \r\n\r\nDas Abenteuer hatte begonnen.[/i]', 11, 'ARCHIV-0', 0),
(11, 2, '2008-11-16 19:25:56', '[i]Es war ein großer Tag auf Olymp. Die ersten Produktionsgebäude hatten Ihre Arbeit aufgenommen und das erste größere Projekt stand an. Nicht nur die Produktion mußte unabhängig vom Iconia-Portal gestaltet werden. Die kleine Transportflotte hatte bereits die ersten Systemausfälle zu verzeichnen. Es mußte eine Werft her um die Schiffe nach dem langen Flug warten und dem Bedarf entsprechend neue Schiffe bauen zu können. So kam es, daß [spieler:11] an einem sonnigen Morgen den Grundstein für eine neue Flotte legte indem er den ersten Spatenstich zur ersten Werft in dieser Galaxis tat. [/i]', 11, 'ARCHIV-1', 0),
(12, 2, '2008-11-17 21:43:31', '[i]Symbiose geglückt....\r\nNahrungserwerb aus Fremdkörper konnte erfolgreich abgeschlossen werden. Abstoßvorgang von dem Wirt beginnt, [Spieler:10] muß sich weiterenwickeln......\r\n\r\nHaben geeigneten Spenderoragnismus gefunden, beginne mit Parasitenbefall.........\r\n\r\nFür [spieler:10]![/i]', 10, 'ARCHIV-0', 0),
(13, 2, '2008-11-18 06:45:46', '[i]Es war später Abend, die Sonne war bereits untergegangen und [spieler:11] las die letzten Tagesberichte:\r\n- Baustoffproduktion: steigend\r\n- Duraniumproduktion: steigend\r\n- Energieproduktion: am Kapazitätenlimit.\r\nDie Produktion machte ihm also keine Sorgen, aber in Kürze würde man sich nach einer neuen Energiequelle umsehen müssen. Die planetaren Reserven waren erschöpft.\r\nIn diesem Moment gellte der Alarm, als auch schon sein Adjutant durch die Tür stürmte:[/i]\r\n´´Sir, eine gewaltige Subraumwelle rast auf den Planeten zu. Es bleibt keine Zeit für Gegenmaßnahmen, Sie sollten sich festhalten.´´\r\n[i]In diesem Moment ging die Welt unter. Der Boden bebte und die Sterne vor dem Fenster verschwanden. Als es vorbei war hatte sich der Himmel verändert, unbekannte Sterne glitzerten am Firmament.\r\n\r\nWas würde die Zunkunft in dieser Galaxis noch bringen?[/i]\r\n', 11, 'ARCHIV-2', 0),
(14, 2, '2008-11-19 20:31:24', '[i][spieler:11] saß mit seinem Adjutanten zusammen und sprach über den letzten eingegangenen Funkspruch.[/i]\r\n\r\n``Soso, man bietet uns also die Baupläne für die Oberthklasse für 160t Baumaterial an? Was sollen wir mit diesem veralteten Schiff? Die Baupläne befinden sich doch im Kernspeicher den wir aus der Heimat mitgebracht haben.``\r\n``Leider Nein Sir, ein Mauerstück hat den Kernspeicher erwischt. Wir werden sämtliche Baupläne neu entwickeln müssen.``\r\n``Wieso wurde ich darüber nicht informiert?``\r\n``Doch Sir, es stand im letzten Schadensbericht, auf der dritten Seite``\r\n``Man, sowas gehört auf die erste Seite. Auf der zweiten Seite ging es schon nur noch um abgeplatzten Putz. Da habe ich einfach nicht weitergelesen. Also setzten Sie sich mit dem Mann in Verbindung. Wir kaufen diese Baupläne. Eine Eigenentwicklung wäre wesentlich teurer.‘‘\r\n``Jawohl Sir.``\r\n\r\n[i]Einige Stunden später transferiert ein Frachter der [b]GCC[/b] 160t Baumaterial zu einer Forschungsstation der [allianz:3]. Kurze Zeit später erhielt [spieler:11] einen Anruf:[/i]\r\n``Sir, der gute Mann scheint ein wenig verwirrt zu sein. Er hat die 160t Baumaterial in Empfang genommen und jetzt will er auch noch 80t Duranium.``\r\n``80t Duranium? Also langsam kommen wir in Bereiche, da hätten wir es für den selben Preis selber entwickeln können. Bekommen wir unser Baumaterial zurück?``\r\n``Nein Sir. Unser [i]Wohltäter[/i] hat eine Technologie entwickelt um Wurmlöcher zu generieren. Der Frachter mit dem Baumaterial ist bereits verschwunden.``\r\n``Dann bleibt uns wohl keine Wahl, wenn das nicht ein 100%iges Verlustgeschäft werden soll. Kommen Sie heim und holen Sie das Duranium ab.``\r\n``Jawohl Sir.``\r\n\r\n[i]Am nächsten Morgen ist der Frachter wieder bei der Raumstation und übergibt das Duranium. Kurz darauf setzt ein Frachter der Station Kurs auf ein Wurmloch und ein Notruf geht ein:[/i]\r\n\r\n``Halten Sie den Frachter auf, er hat das Duranium gestohlen.``\r\n``Zu spät, bis wir auf Fahrt sind ist der Frachter durch das Wurmloch.``\r\n``Schade, dann brauche ich aber noch einmal 80t Duranium``\r\n``Spinnen Sie? Wir haben alles geliefert was sie wollten, jetzt sind sie dran.``\r\n``Jaja, ist ja schon gut, aber dann liefern Sie mir wenigstens das Erz um das Duranium selber herzustellen. Sie bekommen dann auch einen fertigen Prototypen geliefert.``\r\n``Sie haben Glück das ich heute meinen guten Tag und einen vollen Frachtraum habe. Sie sollen Ihr Erz bekommen.``\r\n\r\n[i]Am nächsten Morgen flogen eine nagelneue Oberth und der Frachter im Verband, jeweils mit einer Notbesatzung versehen in Richtung der neuen Heimat.[/i]\r\n', 11, 'ARCHIV-4', 0),
(15, 4, '2012-04-08 22:21:57', 'blub', 1, '-0', 0),
(16, 4, '2012-04-08 22:24:42', 'testbezugspunkt', 1, '-15', 0),
(17, 5, '2012-04-09 00:27:54', 'Dies ist ein Testkanal \r\n\r\n[b][u]Test[/b][/u]', 1, '-0', 0),
(18, 5, '2012-04-09 02:32:59', 'mh hallo', 4, '-0', 0);
INSERT INTO `kn_log` (`id`, `autor`, `text`, `datum`, `pid`, `channel`) VALUES
(1, 10, '[i]Interessant, hier scheint es Leben zu geben. Nil\\\\\\-Nischla, setzten Sie einen Wirt in das Al Niyat-System. Ruhm und Ehre für unsere Zunft sollen auch in diesem gottlosen Sektor Einzug halten. Wir, [spieler:10], werden die niederen Lebensformen studieren und analysieren, noch ist es nicht Zeit uns zu erkennen zu geben. \r\n\r\nDoch bald....[/i]', '2008-11-14 17:45:29', 2, 1),
(2, 4, 'Hab dir gerade im Ingame-Chat geantwortet:\r\n\r\nbei mir auf der kolonien seite stet erst das bild des plani, dann der name, dann der sektor im system und dann der systemname samt sektor\r\nmusst erst zu den system koordinaten fliegen, in dem fall also die zweiten .. dort ins system und zu den plani koords,.. die, die vorne stehe', '2008-11-14 18:53:38', 3, 3),
(3, 1, 'test', '2008-11-14 23:38:48', 3, 1),
(4, 1, 'zft', '2008-11-14 23:48:47', 4, 1),
(5, 4, 'asd', '2008-11-14 23:49:43', 4, 3),
