INSERT INTO `quests` (`id`, `titel`, `text`, `abgabetext`, `max`, `zusatz`, `zusatz2`, `itembeschreibung`, `geber`, `abgeber`, `typ`, `vorquest`, `level`, `bschiffe`, `brohstoffe`, `item`) VALUES
(1, 'Ankunft in der fremden Welt', 'Willkommen junger Siedler,\r\n\r\nmein Name ist nicht von Bedeutung, ich wurde von der Sternenflotte beauftragt mich um die Neuankömmlinge zu kümmern.\r\n\r\nUm ihre Grundversorgung auf ihrem Planeten zu sichern, sollten sie zunächst einmal eine Baustofffabrik errichten.\r\n\r\nGehen Sie dazu auf ihren Planeten ( Planetenreiter ) und klicken sie auf ein gr&uuml;nes Wiesenfeld. \r\nKlicken sie dann im Baumen&uuml; auf die Baustofffabrik.\r\n\r\nDanach melden sie sich im Naviagtionsmen&uuml; unter dem Reiter Quests wieder.', 'Wunderbar. Denken Sie daran: \r\nBaustoff ist der Grundstoff von allem es gibt nichts was ihn nicht ben&ouml;tigt.\r\n\r\nAber Baustoff ist nicht alles. Beenden sie diese Quest, dann werde ich sie aufkl&auml;ren was noch notwendig ist um zu &uuml;berleben.', 1, '1', '', '', 0, 0, 4, 0, 1, '', '', 0),
(2, 'Energiegewinnung', 'Sehr gut!\r\n\r\nSie haben nun eine Anlage mit der sie das Grundelement Baustoff herstellen k&ouml;nnen.\r\n\r\nErrichten sie nun eine Solaranlage in einer W&uuml;ste!\r\n\r\nKlicken sie dazu auf dem Planeten auf ein freies W&uuml;stenfeld und errichten sie eine Solaranlage.', 'Nun achten sie immer darauf genug Energie zur Verf&uuml;gung zu haben.\r\n\r\nAll ihre Geb&auml;de ben&ouml;tigen Energie. Haben sie keine Energie, so produzieren sie auch nichts. Ausserdem braucht man Energie um Waren auf Schiffe zu transferieren oder um planetare Schilde aufzuladen.', 1, '3', '', '', 0, 0, 4, 1, 1, '', '', 0),
(5, 'Kontrollflug ins Sheliak-System', 'Ausgezeichnet,\r\n\r\nda Sie jetzt ihren Planeten ausreichend versorgt haben, teile ich ihnen hiermit ihren neuen Auftrag mit.\r\n\r\nSie haben vom Flottenkommando eine Sonde erhalten. Scannen sie mit dieser das Sheliak-System.\r\n\r\nDie Sonde finden sie unter dem Reiter "Schiffe". W&auml;hlen sie diese aus um zur &Uuml;bersicht zu gelangen.\r\n\r\nNavigieren / Fliegen sie diese Sonde dann zum Sheliak-System, indem sie die roten Pfeile zum navigieren verwenden.\r\n\r\nDas Sheliak-System befindet sich bei 1024|1014 im Weltraum.\r\nUm dorthin zu gelanden, treten sie zun&auml;chst aus dem Orbit aus. Danach k&ouml;nnen sie das System verlassen.\r\n\r\nNun navigieren sie zu den Koordinaten. Und scannen sie das System.\r\n\r\nNach diesem Auftrag sind sie bereit größere Aufgaben zu übernehmen. ', 'Sehen sie? \r\n\r\nMithilfe einer Sonde oder eines anderen Schiffes k&ouml;nnen sie rausfinden welche &uuml;blen Rassen sich dort verstecken.\r\n', 1, '11', '', '', 0, 0, 3, 2, 1, '', '', 0),
(6, 'Deuteriumsammeln', 'Sammeln sie nun mit einem Tankerschiff 60 Einheiten Deuterium.\r\n\r\nDazu w&auml;hlen sie einen Tanker aus und fliegen ihn ein einen kleinen oder grossen Deuteriumnebel.\r\n\r\nSaugen sie dort 60 Deuterium ein.\r\nVergessen sie nicht:\r\nein großer Nebel hat eine hohe Dichte, 1 Energie entspricht 10 Deuteriumsgewinn.\r\nein kleiner nebel f&ouml;rdert nur die H&auml;lfte zu Tage.', 'Sensationell.\r\n\r\nAchten sie darauf. Jedes Schiff brauch Deuterium sammeln sie also viel und verteilen sie es auf ihre Schiffe!\r\n', 60, 'deuterium', '', '', 0, 0, 7, 0, 2, '', '', 0),
(7, 'Erzsammeln', 'Sammle mit einem Erzfrachter 70 Erzeinheiten.', 'Unglaublich !', 70, 'erz', '', '', 0, 0, 7, 0, 2, '', '', 0),
(8, 'Computerkerne', 'Wir haben im Weltraum in der gesamten Schutzzone mehrere Tr&uuml;mmerteile. Bringen sie deren Computerkerne zu mir, damit wir untersuchen k&ouml;nnen was hier vor sich ging\r\n\r\nZusammenfassung:\r\nSammeln sie die Computerkerne von 5 Wrackteilen.', 'Sehr gut,\r\n\r\nwir werten die Informationen dieser Kerne aus. Sehr gut.\r\n\r\nWenn sie alle Quests beendet haben, erhalten sie ein Level up.', 5, 'Kristalle', '9', '', 0, 0, 6, 7, 2, '', '', 8),
(11, 'Heimische Erze', 'Nun sie haben es geschafft Erze aus dem Weltraum abzubauen.. unglaublich!!\r\n\r\n<i>Der beauftrage Offizier scheint nicht sehr beeindruckt.</i>\r\n\r\nWarum versuchen sie nicht mal eine Mine auf ihrem Planeten zu bauen. Sie hilft ihnen Erze ersteinmal aus dem Planeten zu f&ouml;rdern bevor sie gleich den ganzeh Weltraum anzapfen.\r\n\r\nBauen sie eine Erzmine!', 'Siehe da sie haben es geschafft eine Mine zu bauen, jetzt m&uuml;ssen sie nicht immer tausende Kilometer im Weltraum zur&uuml;cklegen um an ihr Erz zu kommen\r\n\r\n<i>Der Offizier lacht lauthals</i>.', 1, '8', '', '', 0, 0, 4, 7, 2, '', '', 0),
(13, 'Erz &uuml;berall Erz...', 'Sie schon wieder. Sie wissen nicht was sie mit ihren Erzen machen sollen\r\n\r\n<i>Der alte offizier muss wieder lauthals lachen</i>\r\n\r\nAlso passen sie auf Junge.\r\nBauen sie doch mal eine Duraniumanlage.\r\nDiese Dinger verwandeln ihre erze in hartes Duranium, das brauchen sie um ihre ersten Schiffe zu bauen.\r\n\r\nAlso, bauen sie eine Duraniumanlage!', 'Ist es nicht herrlich. Bald k&ouml;nnen sie ihr erstes Schiff bauen.', 1, '9', '', '', 0, 0, 4, 11, 2, '', '', 0),
(14, 'Oberth', 'Sie wollen also eine Oberth bauen ?\r\n\r\nIch hab keine Ahnung wie man sowas macht, ich bin angestellt um Jungspunden Respekt einzubringen.\r\n\r\nAber fragen sie doch mal in der Sternenbasis 12 nach, wenn ich mich richtig erinnere liegt sie bei 175|129 herum.\r\n\r\nFliegen Sie zur Sternenbasis 12 und holen sie Informationen ein zur Oberth.\r\n\r\n', 'Ich gr&uuml;sse sie Captain.\r\n\r\nMh Oberth sagen sie. Um ehrlich zu sein haben wir die Baupl&auml;ne nicht mehr..\r\n\r\nAber warten sie ich suche mal etwas heraus reden sie gleich nochmal mit mir!', 0, '', '', '', 0, 396, 8, 0, 4, '', '', 0),
(15, 'Oberth', 'Ja da ist es ja.\r\n\r\nbei den Koordinaten 172|139 befindet sich eine Forschungsstation eines unserer verr&uuml;ckte... ich meine brilliansten Wissenschaftler. Er ist ein Datenmessi.\r\n\r\nEr hat die Pl&auml;ne bestimmt noch.', '<i>Ein verwirrter Mann meldet sich auf dem Bildschirm</i>\r\n\r\nWAS? OBERTH! ja nat&uuml;rlich habe ich die Baupl&auml;ne. Am besten ich helfe ihnen so ein Ding zu bauen dann wissen sie gleich wie es geht. Dazu brauche ich aber Materialien, sprechen sie mich gleich nochmal an. \r\n\r\nIch suche sie heraus!\r\n\r\n<i>Der Mann kramt in Datenpadds herum</i>', 0, '', '', '', 396, 397, 8, 14, 4, '', '', 0),
(16, 'Obert: Baustoffe', 'Ja also ich brauche 160 Baustoffe. tehe. \r\n\r\nMh Ich verstehe euch, ihr seit zuweit von eurem Heimatplaneten entfernt. Nun gut.\r\n\r\n<i>fl&uuml;stert: Ich habe geheime Technologie, sie erlaubt mir Wurml&ouml;cher &ouml;ffnen.</i>\r\n\r\nDamit k&ouml;nnt ihr schnell eure Materialien holen.', 'Sehr gut!\r\n\r\nDanke f&uuml;r die Baumaterialien.\r\nAber das war nicht alles...\r\n\r\nWas war da nochmal...', 160, 'baustoff', '', '', 397, 397, 2, 15, 4, '', '', 0),
(17, 'Oberth: Duranium', 'Achja.. naja ich bin etwas vergesslich.\r\n\r\nMan braucht nat&uuml;rlich noch 80 Duranium..\r\n\r\nEntschuldigt!', 'So, ich denke das geht in Ordnung dann versuchen wir mal unser Gl&uuml;ck.\r\n\r\nSprecht mich gleich nochmal an.', 80, 'duranium', '', '', 397, 397, 2, 16, 4, '', '', 0),
(18, 'Oberth: noch mehr Material?', 'Nun...\r\n<i>der Mann stottert</i>\r\n\r\nich hab da so einen Jungen eingestellt... Er verlangt keine Entsch&auml;digung... ach was solls.\r\nMir ist euer Duranium verlorengegangen.\r\n\r\nBringt mir noch 300 Erze dann kann ich euer Schiff fertig bauen.\r\n\r\n', 'SO! Endlich.\r\n\r\nDanke f&uuml;r euer Erz! \r\n\r\nEure Ingeneure haben alles notiert, sie sollten jetzt auch in der Lage sein, die Oberth zu bauen.\r\n\r\nDer Prototyp ist durch das Wurmloch zu euren Heimatplaneten geflogen, dummerweise ist das Wurmloch danach kollabiert ihr m&uuml;sst wohl mit diesem Schiff den langen Weg fliegen.\r\n\r\nDazu hab ich euren Deuteriumvorrat um 100 aufgestockt. \r\n\r\nBis Bald', 300, 'erz', '', '', 397, 397, 2, 17, 4, 'Oberth', 'deuterium-100', 0),
(20, 'Der Planet ist nicht genug...', 'Sie haben mittlerweile einige Erfahrungen in dieser Welt gesammelt.\r\n\r\nUm allerdings selber in den Weltraum aufzubrechen, brauchen sie ein Geb&auml;ude was in der Lage ist Schiffe zu bauen.\r\n\r\nGehen sie auf ihre Planetenoberfl&auml;che und bauen sie eine Werft auf einem Eisfeld.', 'Ihre Werft ist gerade in Betrieb gegangen.\r\nAusgezeichnet!\r\n\r\nSie sind jetzt in der Lage selber Tanker, Frachter und Sonden zu bauen.\r\n\r\nMit der Zeit werden sie auch Kriegsschiffe herstellen k&ouml;nnen.', 1, '4', '', '', 0, 0, 4, 0, 3, '', '', 0),
(21, 'A.W.M.E.', 'Die Politik wirbt derzeit vermehrt mit der neuen Aus Wasser mach Energie - Kampagne.\r\n\r\nVersuchen sie es auch einmal und bauen sie 2 Wasserkraftwerke auf ihren Wasserfeldern.\r\n\r\n', 'Sehr praktisch, aus nichts wird Energie erzeugt.\r\n\r\nIhr Planet ist jetzt schon sehr gut ausgebaut, sie sind bald bereit f&uuml;r den Umzug...', 2, '7', '', '', 0, 0, 4, 20, 3, '', '', 0),
(22, 'der grosse Umzug - Vorbereitungen', 'Es ist soweit! \r\nSie sind bereit die Schutzzone zu verlassen und ins "echte" Leben einzutauchen.\r\n', 'Sehr gut. es kann losgehen...\r\n\r\nIm Reiter Quests k&ouml;nnen sie nun eine Stufe aufsteigen und endlich umziehen!', 0, '', '', '', 0, 0, 8, 21, 3, '', '', 0),
(23, 'Welcome to the real world!', '<i>der Offizier murmelt: Niemand nimmt die blaue Pille!</i>\r\n\r\nNun... sie sind angekommen. \r\nNur zu ihrer Informationen, sie sind nun angreifbar, achten sie also auf ihre Verteidigung.\r\n\r\nSie werden von mir mehrere Aufgaben bekommen, aber lassen sie mich zuerst erkl&auml;ren was sie jetzt erwartet.\r\n\r\nSie sind auf Level 4 und k&ouml;nnen alle anderen Siedler die selbiges Erfahrungslevel besitzen angreifen oder beklauen. Nat&uuml;rlich k&ouml;nnen sie selber auch angegriffen werden.\r\n\r\nDesweiteren werde ich ihnen zeigen wie man ein erstes Kriegsschiff bauen kann.', 'So gleich gehts los beenden sie diese Quest um endlich die Verteidigung zu aktivieren, denn ...', 0, '', '', '', 0, 0, 8, 0, 4, '', '', 0),
(24, '... Angriff ist die beste Verteidigung!', 'Nun, jeder weiss es. Wenn hier eine Batterie von Kanonen steht, wird sich wohl kaum einer hertrauen. \r\n\r\nZur Information: Eine Plasmakanone hat eine Feuerkraft der Stufe 6, beachtlich!\r\n\r\nBaut eine Plasmakanone!', 'Ich selbst habe meinen Heimatplaneten mit 5 St&uuml;ck gesichert.\r\nSchildt&uuml;rme? was ist das ...\r\n\r\n<i>der Offizier lacht</i>', 1, '5', '', '', 0, 0, 4, 23, 4, '', '', 0),
(26, '...vielleicht auch nicht!', 'Ich habe gerade erfahren, dass mein Heimatplanet angegriffen wurde. Dummerweise standen meine Kanonen nur auf einer Planetenseite.\r\n\r\n<i>Der Offizier flucht</i>\r\n\r\nVielleicht ist es daher doch angebracht wenn sie wenigstens 1 Schildturm bauen!\r\n', 'Jetzt kann ihnen eigentlich nichts mehr passieren.\r\n\r\nDenken sie daran all ihre Kolonien zu sch&uuml;tzen. Ihr Heimatplanet kann zwar nicht bombadiert werden, dennoch kann man ohne Schilde ihre Waren klauen.', 1, '6', '', '', 0, 0, 4, 24, 4, '', '', 0),
(27, 'Forschungslabor', 'Nun da sie endlich begriffen haben wie man eine Kolonie aufbaut, wird es aber Zeit zu forschen!\r\n\r\nSie fragen mich was sie erforschen sollen? Das ist mir gaenzlich egal, bauen sie eine Forschungsstation, das ist ein Befehl\r\n\r\n<i>Der launische Offizier moechte das sie eine Forschungsstation bauen!</i>', 'Wie ich sehe hat sich ein Teil ihrer Bev&ouml;lkerung einen Kittel angezogen und schwenkt Reagenzgl&auml;ser... Ob das reicht? \r\n\r\nAls kleinen Ansporn erhalten sie 4 Isochips...', 1, '10', '', '', 0, 0, 4, 0, 5, '', 'isochips-4', 0),
(28, 'Die Oberth ist nicht genug....', 'Sie wollen also hoch hinaus, dabei haben sie doch 0 Verständniss für die Schönheit der Schiffe.\r\nNagut es geht Ihnen offensichtlich nur um den Nutz Wert. Lasst mich doch mal schauen.. ja meine Isochips sind sehr knapp geworden, bringt mir doch <b>40 Isochips</b>, dann schau ich mal ob ich die Baupl&auml;ne finde...', 'Wunderbar Hier ist es auch schon:\r\n\r\nDie Miranda! Ein prachtvolles Schiff.\r\nDa gibt es nur noch ein Problem....', 40, 'isochips', '', '', 397, 397, 2, 27, 5, '', '', 0),
(29, 'Duranium? Tritanium!', 'Nun um das Schiff herzustellen brauch man den seltenen Rohstoff Tritanium. Es gibt verschiedene M&ouml;glichkeiten an diesen Rohstoff heranzukommen.\r\n\r\n- Produziert es selber auf einem W&uuml;stenplaneten.\r\n- Kauft euch welches an der Warenb&ouml;rse\r\n\r\nBesorgt 20 Einheiten Tritanium', 'Sehr gut ihr habt es geschafft!\r\n\r\nJetzt fehlt nur noch eins!!', 20, 'tritanium', '', '', 397, 397, 2, 28, 5, '', '', 0),
(30, 'Warpkerne', 'Der Prototyp Ihrer Miranda braucht einen speziellen Warpkern! Der Grund? Was fragen sie mich nach dem Grund! Ich bin hier der Techniker.\r\nZuf&auml;llig testen sie damit gleichzeitig meine neue Technologie, was nat&uuml;rlich hier nicht die Hauptsache ist.\r\n\r\nFliegen sie mit einem bewaffneten Schiff in das Wurmloch bei 167|138. Dort finden sie eine kleine Romulanerflotte vor. Erbeuten sie einen intakten Warpkern aus einem ihrer Tr&uuml;mmer. Ja dieses Vorgehen ist hart, aber notwendig!\r\n\r\nDas Heimatwurmloch ist bei 800|800', 'Wunderbar mit diesem Warpkern konnte ich eine Miranda bauen.\r\n\r\nDer Prototyp sollte schon bei ihrem Heimatplaneten angekommen sein!', 1, '10', '6', '', 397, 397, 6, 29, 5, 'Miranda', '', 10),
(31, 'der verschwundene Sp&auml;her', 'Ich empfange euch in traurigen Gr&uuml;ssen,\r\n\r\nder Weihnachtsmann wurde entf&uuml;hrt!\r\nJa ihr habt richtig geh&ouml;hrt.\r\nEr war in einem der benachbarten Systeme unterwegs gewesen um noch Geschenkpapier zu kaufen.\r\n\r\nSucht die Systeme ab und sprecht mit seinem Assistenten Niqolouz.', 'Ihr wisst es schon?\r\n<i>Der Wichtel bricht in Tr&auml;nen aus</i>\r\n\r\nWir befanden uns auf dem Weg zu einem fliegenden H&auml;ndler. Er wollte uns g&uuml;nstiges Geschenkpapier besorgen.\r\nDen Namen k&ouml;nnt ihr nicht ausprechen... \r\nWie auch immer. Es tauchten abtr&uuml;nnige Weihnachtswichtel auf undzwar 3 Schiffe von den VW, den verbannten Weihnachtswichteln.\r\n\r\nSie entf&uuml;hrten den Weihnachtsmann, aber keine Sorge ich habe einen Plan...\r\n\r\nWenn ihr uns helfen wollt den Weihnachtsmann zur&uuml;ck zu holen, dann sprecht Morgen am 2. Dezember wieder mit mir! ( Niqolouz )', 0, '', '', '', 2463, 2464, 8, 0, 0, '', '', 0),
(32, 'Motivation', 'Wiegesagt, ich habe einen Plan. Im gesamten Crown-System findet Ihr Tr&uuml;mmer unserer Schlitten. Auf den Schlitten sind sehr wichtige G&uuml;ter die wir unbedingt brauchen als Treibstoff. Lebkuchen! Nein nat&uuml;rlich funktionieren unsere Schiffe nicht mit Deuterium! \r\n\r\nAlso fliegt ins Crown-System besorgt mir 4 Lebkuchen und kommt zu mir zur&uuml;ck.', 'Sehr gut!\r\n\r\nWir haben einen Vorposten der VW ausgemacht.\r\nDie Lebkuchen helfen unseren Wichteln genug Energie aufzubringen um eine kleine Angriffsflotte zusammenzustellen.\r\n\r\nSprecht wieder mit mir am 3.Dezember', 4, '', '9', '', 2464, 2464, 6, 31, 0, '', '', 11),
(33, 'Angriff!', 'Es ist soweit. Wir haben den Vorposten im Grise-System ausgemacht! Begebt euch dort hin und zerst&ouml;rt den Vorposten!\r\n\r\nDa diese Augabe etwas anspruchsvoller ist, sprecht mich erst wieder am 5. Dezember an!\r\n\r\nHinweis:\r\nDiese Quest k&ouml;nnt ihr als Gruppe erledigen.\r\nIn einer Gruppe k&ouml;nnen bis zu 5 Spieler sein.\r\nDazu m&uuml;ssen alle Spieler in de Gruppe sein UND alle die Quest angenommen haben.\r\n\r\nMan kann eine Gruppe er&ouml;ffnen unter \r\nKommunikation -> Vertr&auml;ge / Diplomatie.\r\n\r\nDer Vorteil von Gruppen: wenn alle Gruppenmitglieder mit ihrem Schlitten auf dem Feld des Vorpostens stehen und der Vorposten wird von einem der Gruppenmitglieder vernichtet, so z&auml;hlt die Vernichtung f&uuml;r die Quests ALLER Gruppenmitglieder!\r\n\r\nDie Station taucht wenn vernichtet alle 15 Min wieder auf, daher wird zu Gruppenarbeit geraten!', 'Ausgezeichnet!\r\n\r\nIhr habt euch eine Pause verdient, wir sprechen uns am 5. Dezember wieder!', 1, '16', 'Vorposten', '', 2464, 2464, 1, 32, 0, '', '', 0),
(34, 'Wir haben ihn gefunden....', 'Wir haben etwas gefunden, der &Uuml;belt&auml;ter befindet sich im Crown System sehr weit "s&uuml;dlich".\r\n\r\nZerst&ouml;rt sein Schiff und bringt mir seine Fracht!', 'Sehr gut, ich werde einen Tag brauchen um die Carbonith&uuml;lle aufzutauen, dann wissen wir ob er &uuml;berlebt hat!', 1, '12', '16', '', 2464, 2464, 6, 33, 0, '', '', 12),
(35, 'Nikolaus', 'Ich habe ihn endlich aufgetaut, leider war es nicht der Weihnachtsmann, aber wie der Zufall es so wollte habt ihr den Nikolaus befreit.\r\nIch wusste zwar nicht einmal dass er vermisst wird, aber nun denn! \r\n\r\nSprecht mich gleich nocheinmal an\r\n', 'Zur Feier des Tages kosten wir unseren Triumph aus!\r\n\r\nIhr erhaltet alle 10 Isochips auf euer Warenkonto.\r\n\r\nSprecht mich am 7. Dezember wieder an!', 0, '', '', '', 2464, 2464, 8, 34, 0, '', '', 0),
(36, 'Erkundungstour', 'Ich verstehe.\r\nIhr sagt also 4 Planeten reichen euch nicht?\r\n\r\nDann tut etwas, ich glaube man kann diese eigenartigen Monde besiedeln... das hat mir mal ein gewisser Matthias erzählt. Jaja dieser Matthias....\r\n\r\nÄh wo war ich ? Achja? Scannt einen dieser O-Monde. \r\n\r\n<img src="http://pdhoen.de/temp/ga2/omond2.png">\r\n', 'Sehr gut, ich werte eben die Daten aus mit unserem modernen Zeh 64.\r\n\r\nSprecht mich gleich nochmal an', 1, 'om', '', '', 0, 0, 9, 0, 5, '', '', 0),
(37, 'Noch mehr Erforschungen!', 'Sehr gut, der Zeh 64 hat sehr lange gerechnet und!....\r\n\r\n... nun ist er kaputt verdammt.\r\nWir brauchen eine Weile um ihn zu reparieren, fliegt einfach mal los und scannt einen Klasse - M Mond\r\n\r\n<img src="http://www.pdhoen.de/temp/ga2/mmond2.png">\r\n\r\nWas? Nein wir brauchen die Daten nicht, aber sie sollen sich ja nicht langweilen.\r\n\r\n<i>Der Ingenieur kramt in seiner Werkzeugkiste...</i>', 'Sehr gut! Der Zeh 64 l&auml;uft wieder!\r\n\r\nGebt mir die Daten von vorhin nocheinmal, ich werde sie auswerten.\r\n\r\nSprecht mich gleich nochmal an!', 1, 'mm', '', '', 0, 0, 9, 36, 5, '', '', 0),
(38, '... Landau?', 'Nun.. wir haben die Daten auswerten k&ouml;nnen, zumindest zum Teil.\r\n\r\nDer Rechner l&auml;uft noch.\r\nIhr wollt den Grund? Habt ihr schonmal etwas von der "Gabrecht" Theorie geh&ouml;rt? Nein!? \r\n\r\nDann lasst uns bitte arbeiten. Weil alle guten Dinge 3 sind, scannt doch bitte noch einen Mond der L - Klasse\r\n\r\n<img src="http://www.pdhoen.de/temp/ga2/lmond2.png">\r\n', 'Sehr gut, wir sind endlich fertig.\r\n\r\nWir &uuml;berspielen ihrem Zentralcomputer die Informationen wie man Monde besiedelt!\r\n\r\nIhr k&ouml;nnt jetzt 5 Planeten und 1 Mond insgesamt besiedeln.\r\n', 1, 'lm', '', '', 0, 0, 9, 37, 5, '', '', 0);
