INSERT INTO `tip` (`id`, `text`) VALUES
(2, 'Du kannst Erz auch mit Erzfrachtern aus Asteroidenfeldern abbauen.'),
(3, 'Achte darauf deinen Planeten mit Schildtürmen vor Rohstoffdiebstahl zu schützen.'),
(4, 'Ohne Deuterium wird dein Schiff bald keine Energie mehr haben, versorge deine Schiffe mit diesem wichtigen Treibstoff.'),
(5, 'mehrere Schildtürme addieren die Schildstärke auf deinem Planeten!'),
(6, 'Dein erster Planet ist permanent geschützt gegen Bombadierung der Gebäude, nicht aber vor angriffen auf die planetaren Schilde.');
